const resp = $input.first().json || {};
const records = Array.isArray(resp.records) ? resp.records : [];
const hoy = new Date();
const out = [];
for (const rec of records) {
  const f = rec.fields || {};
  const resultado = String(f['Resultado'] || '');
  if (resultado !== 'Interesado' && resultado !== 'Volver a pasar') continue;
  if (f['FU pausado'] === true) continue;
  const etapa = parseInt(f['FU etapa'] || 0) || 0;
  if (etapa >= 3) continue;
  // Ancla del conteo de dias: "Fecha siguiente accion" (la que el comercial declara en el
  // checklist como disparador de WF-P2) - si falta o es invalida, cae a "Fecha" (fecha de
  // la visita) como respaldo. Antes solo usaba "Fecha", ignorando el campo pensado para esto.
  let fv = new Date(String(f['Fecha siguiente acción'] || ''));
  if (isNaN(fv.getTime())) fv = new Date(String(f['Fecha'] || ''));
  if (isNaN(fv.getTime())) continue;
  const dias = Math.floor((hoy.getTime() - fv.getTime()) / 86400000);
  let objetivo = 0;
  if (dias >= 7) objetivo = 3; else if (dias >= 3) objetivo = 2; else if (dias >= 1) objetivo = 1;
  if (objetivo <= etapa) continue;
  let siguiente = etapa + 1;
  if (siguiente < objetivo) siguiente = objetivo;
  const prospLink = Array.isArray(f['Prospecto']) ? f['Prospecto'] : [];
  out.push({ json: {
    recordId: rec.id,
    prospectoId: prospLink[0] || '',
    etapa: siguiente,
    dias: dias,
    emailVisita: String(f['Email contacto'] || '').trim(),
    nombreVisita: String(f['Nombre contacto'] || '').trim(),
    showroom: String(f['Showroom'] || 'vuestro showroom'),
    informeUrl: String(f['Informe URL'] || '').trim()
  } });
}
return out;

const items = $input.all();
const cands = $('Preparar candidatas').all();
const MAIL_FROM = 'Black Label Market <hola@blacklabelmarket.es>';
const alta = 'https://blacklabelmarket.es/profesionales/solicitar-acceso';

const legalFooter = '<div style="margin-top:24px;padding-top:14px;border-top:1px solid #ddd;font-size:11px;color:#777;line-height:1.5">' +
  'Black Label Market es una marca de <strong>KAZAWEB, S.L.U.</strong> (NIF B42761254), con domicilio en Lugar Rebordelo nº 35, Planta 2, 15930 Boiro, A Coruña. Inscrita en el Registro Mercantil de Santiago de Compostela, Tomo 395, Folio 51, Hoja SC-51053.<br>' +
  'Puedes solicitar la baja de comunicaciones o ejercer tus derechos de privacidad escribiendo a <a href="mailto:privacidad@blacklabelmarket.es">privacidad@blacklabelmarket.es</a>. Consulta nuestra <a href="https://blacklabelmarket.es/legal/privacidad">Política de Privacidad</a>.' +
  '</div>';

function emailPara(e) {
  if (e.etapa === 1) {
    return { subject: 'La plaza fundador de ' + e.showroom,
      html: '<p>Buenas ' + e.nombre + ',</p>' +
        '<p>Gracias por el tiempo en la visita. Como hablamos, el Programa Fundador os deja publicar vuestro stock en Black Label Market sin coste durante el lanzamiento &mdash; nosotros nos encargamos de subirlo. Es un programa con solo 20 plazas a nivel nacional, así que si os interesa entrar, mejor no dejarlo para más adelante.</p>' +
        '<p>Dejar la solicitud son 2 minutos: <a href="' + alta + '">' + alta + '</a></p>' +
        '<p>Un saludo,<br>Black Label Market</p>' + legalFooter };
  }
  if (e.etapa === 2) {
    return { subject: 'Lo que os ofrece Black Label Market como fundadores de ' + e.showroom,
      html: '<p>Buenas ' + e.nombre + ',</p>' +
        '<p>Una cosa más sobre el Programa Fundador, por si ayuda a decidir: Black Label Market es un marketplace especializado en vehículos premium &mdash; compradores que buscan específicamente lo que vosotros vendéis, no un clasificado genérico. Como fundadores, nosotros subimos vuestro stock, cada ficha lleva un asistente que atiende consultas de compradores en cualquier momento, y todo esto sin coste durante el lanzamiento.</p>' +
        '<p>Si os encaja, aquí tenéis el enlace para solicitarlo: <a href="' + alta + '">' + alta + '</a></p>' +
        '<p>Un saludo,<br>Black Label Market</p>' + legalFooter };
  }
  return { subject: 'Confirmadnos que no os interesa la plaza fundador',
    html: '<p>Buenas ' + e.nombre + ',</p>' +
      '<p>Cierro el seguimiento sobre esto, salvo que me digáis lo contrario. El Programa Fundador tiene solo 20 plazas a nivel nacional &mdash; es lo que nos permite dar a cada showroom fundador la atención y visibilidad que prometemos.</p>' +
      '<p>Si ya no os interesa entrar, confirmádmelo con un email y libero la plaza para otro showroom.</p>' +
      '<p>Si seguís interesados, dejar la solicitud son 2 minutos: <a href="' + alta + '">' + alta + '</a> &mdash; nosotros publicamos vuestro stock.</p>' +
      '<p>Un saludo,<br>Black Label Market</p>' + legalFooter };
}

const salida = [];
for (let i = 0; i < items.length; i++) {
  const cand = cands[i] ? cands[i].json : {};
  const prospFields = (items[i].json && items[i].json.fields) ? items[i].json.fields : {};
  const email = cand.emailVisita || String(prospFields['Email'] || '').trim();
  if (!email || email.indexOf('@') < 1) continue;
  const nombre = cand.nombreVisita || String(prospFields['Nombre'] || '').trim() || 'buenas';
  const e = { etapa: cand.etapa, showroom: cand.showroom, informeUrl: cand.informeUrl, nombre: nombre };
  const m = emailPara(e);
  salida.push({ json: {
    recordId: cand.recordId, etapa: cand.etapa, dias: cand.dias,
    email: email, nombre: nombre, showroom: cand.showroom,
    emailFrom: MAIL_FROM, emailSubject: m.subject, emailHtml: m.html
  } });
}
return salida;

const item = $input.first();
const d = item.json || {};
const errInfo = d.error || item.error || 'error desconocido';
return [{ json: { ...d,
  taskTitle: 'Fallo email seguimiento visita - ' + (d.showroom || '(sin nombre)'),
  taskEvidence: 'Etapa ' + d.etapa + ' (dias=' + d.dias + '). Email destino: ' + d.email + '. Error: ' + JSON.stringify(errInfo).slice(0, 500),
  slackText: '*Fallo en email de seguimiento post-visita*\n\n*Showroom:* ' + (d.showroom || '?') + '\n*Etapa:* ' + d.etapa + '\n*Email:* ' + d.email,
} }];
